// The scheduler: claims a session for a runner and hands it the next turn.
import { Queue } from './queue';

/** A scheduler of turns. */
export class Scheduler {
  constructor(private readonly queue: Queue) {}

  /** Claim the next turn for a runner, or null when there is none. */
  async claim(runner: string): Promise<string | null> {
    return this.queue.pop(runner);
  }
}

// dispatchTurn hands a claimed turn to its runner exactly once.
export function dispatchTurn(turn: string): boolean {
  return turn !== '';
}

export const LEASE_SECONDS = 60;

